/**
 * GSJS item metadata for every recipe input/output and tool
 * (assets/content/making-items.json, generated by build-recipes.mjs).
 * @type {Record<string, { label: string, namePlural?: string, desc: string, baseCost?: number, stackMax?: number, tags?: string[], isTool?: boolean, pointsCapacity?: number, use?: { kind: 'food'|'drink', verb: string, energy?: number, mood?: number, xp?: number, source?: string } }>}
 */
export let MAKING_ITEM_META = {};

/**
 * Register GSJS item metadata (labels, descriptions, base cost, stack cap,
 * tags) and eat/drink uses with exact source metabolics.
 * @param {{ items?: Record<string, object> } | Record<string, object>} data
 */
export function setMakingItemMeta(data) {
  const items = data && typeof data === 'object' ? data.items || data : null;
  if (!items || typeof items !== 'object') return;
  MAKING_ITEM_META = { ...items };
  ensureMakingItems();
}

/**
 * Replace catalog with GSJS-extracted table (or merge).
 * @param {Record<string, Recipe>} data
 */
export function setRecipeCatalog(data) {
  if (!data || typeof data !== 'object') return;
  RECIPE_CATALOG = { ...data };
  recipesReady = true;
  ensureMakingItems();
}

export function isRecipeCatalogReady() {
  return recipesReady || Object.keys(RECIPE_CATALOG).length > 3;
}

/**
 * Browser: fetch assets/content/recipes.json
 * @param {typeof fetch} [fetchImpl]
 */
export async function loadRecipeCatalog(fetchImpl = globalThis.fetch) {
  if (!fetchImpl) {
    ensureMakingItems();
    return RECIPE_CATALOG;
  }
  try {
    const [res, itemsRes] = await Promise.all([
      fetchImpl('assets/content/recipes.json?v=fruit-machine-2&catalog=recipes-full-3'),
      Promise.resolve()
        .then(() => fetchImpl('assets/content/making-items.json?v=door-1'))
        .catch(() => null),
    ]);
    if (itemsRes?.ok) {
      try {
        MAKING_ITEM_META = { ...((await itemsRes.json())?.items || {}) };
      } catch {
        /* item metadata is optional */
      }
    }
    if (res.ok) {
      const data = await res.json();
      setRecipeCatalog(data);
      return RECIPE_CATALOG;
    }
  } catch {
    /* keep embedded */
  }
  ensureMakingItems();
  return RECIPE_CATALOG;
}

/**
 * Node/tests: load from absolute path to recipes.json
 * @param {string} filePath
 */
export async function loadRecipeCatalogFromFile(filePath) {
  const { readFile } = await import('node:fs/promises');
  const { dirname, join } = await import('node:path');
  try {
    const meta = JSON.parse(await readFile(join(dirname(filePath), 'making-items.json'), 'utf8'));
    MAKING_ITEM_META = { ...(meta?.items || {}) };
  } catch {
    /* sibling metadata is optional */
  }
  const data = JSON.parse(await readFile(filePath, 'utf8'));
  setRecipeCatalog(data);
  return RECIPE_CATALOG;
}

